const input = $input.first().json;
const taskId = input.task_id || new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-audit';
const brief = input.brief || 'Write a 500-word academic essay with APA 7 citations.';
const rubric = input.rubric || 'Thesis & Argument (30%), Evidence & Citations (30%), Organization (20%), Mechanics & Length (20%)';
const draft = input.draft_text || input.full_draft_markdown || input.query || 'Sample draft text for testing the rubric checker.';
const targetWords = Number(input.target_word_count) || 500;

const words = draft.trim().split(/\s+/).filter(Boolean).length;
const minWords = Math.floor(targetWords * 0.95);
const maxWords = Math.ceil(targetWords * 1.05);
const withinWordTolerance = words >= minWords && words <= maxWords;

const verifyTags = (draft.match(/\[VERIFY\]/gi) || []).length;
const inlineCitations = (draft.match(/\([A-Za-z][^)]*,\s*\d{4}[^)]*\)|\[\d+\]/g) || []).length;
const headingsCount = (draft.match(/^#{1,6}\s+.+/gm) || []).length;

return [
  {
    json: {
      task_id: taskId,
      brief,
      rubric,
      draft_text: draft,
      target_word_count: targetWords,
      actual_word_count: words,
      allowed_word_range: `${minWords} - ${maxWords}`,
      within_5_percent_tolerance: withinWordTolerance,
      inline_citation_count: inlineCitations,
      verify_flag_count: verifyTags,
      heading_count: headingsCount,
      report_filename: `${taskId}-rubric-report.md`
    }
  }
];

